"use client";

import { useState, useRef } from 'react';
import { useAppStore } from '@/lib/store';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Upload, X, Save, GripVertical, Eye } from 'lucide-react';
import { MediaRenderer } from '@/components/media-renderer';
import { HtmlLogPreview } from '@/components/html-log-preview';
import type { Comic } from '@/lib/types';
import { useToast } from "@/hooks/use-toast";

interface ComicUploadFormProps {
  type?: 'long' | 'short';
  initialType?: 'long' | 'short';
  category?: string;
  initialCategory?: string;
  initialData?: Comic;
  onClose?: () => void;
  onSuccess?: () => void;
}

export function ComicUploadForm({ 
  type: propType, 
  initialType,
  category: propCategory, 
  initialCategory,
  initialData, 
  onClose,
  onSuccess 
}: ComicUploadFormProps) {
  const { addComic, updateComic } = useAppStore();
  const { toast } = useToast();
  const editMode = !!initialData;
  const type = propType || initialType || 'short';
  const category = propCategory || initialCategory || '';
  
  const [title, setTitle] = useState(initialData?.title || '');
  const [description, setDescription] = useState(initialData?.description || '');
  const [images, setImages] = useState<string[]>(initialData?.images || []);
  const [isSaving, setIsSaving] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [htmlQueue, setHtmlQueue] = useState<{ text: string, fileIndex: number }[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // HTML5 Drag and drop state
  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    
    files.forEach((file, fileIndex) => {
      // Intercept HTML for specific parsing
      if (file.type === 'text/html' || file.name.endsWith('.html') || file.name.endsWith('.htm')) {
        const reader = new FileReader();
        reader.onload = (event) => {
          setHtmlQueue(prev => [...prev, { text: event.target?.result as string, fileIndex }]);
        };
        reader.readAsText(file);
      } else {
        const reader = new FileReader();
        reader.onload = (event) => {
          const result = event.target?.result as string;
          setImages(prev => [...prev, result]);
        };
        reader.readAsDataURL(file);
      }
    });

    e.target.value = '';
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  const moveImage = (fromIndex: number, toIndex: number) => {
    setImages(prev => {
      const newImages = [...prev];
      const [removed] = newImages.splice(fromIndex, 1);
      newImages.splice(toIndex, 0, removed);
      return newImages;
    });
  };

  const handleDragStart = (index: number) => {
    dragItem.current = index;
  };

  const handleDragEnter = (index: number) => {
    dragOverItem.current = index;
  };

  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null && dragItem.current !== dragOverItem.current) {
      moveImage(dragItem.current, dragOverItem.current);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Necessary to allow dropping
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || images.length === 0) return;

    setIsSaving(true);
    
    // Simulate save delay
    await new Promise(resolve => setTimeout(resolve, 500));

    if (editMode && initialData) {
      updateComic(initialData.id, {
        title: title.trim(),
        description: description.trim(),
        thumbnailUrl: images[0],
        images,
        type,
        category,
      });
    } else {
      addComic({
        id: Date.now().toString(),
        title: title.trim(),
        description: description.trim(),
        thumbnailUrl: images[0],
        images,
        type,
        category,
        createdAt: new Date().toISOString(),
      });
    }

    toast({
      title: editMode ? "작품이 수정되었습니다." : "새 작품이 업로드되었습니다.",
      description: "작업을 성공적으로 저장했습니다.",
    });

    setTitle('');
    setDescription('');
    setImages([]);
    setIsSaving(false);
    
    if (onSuccess) onSuccess();
    if (onClose) onClose();
  };

  return (
    <div className="p-6 rounded-2xl bg-card border border-border">
      {htmlQueue.length > 0 && (
        <HtmlLogPreview
          isOpen={true}
          onClose={() => setHtmlQueue(prev => prev.slice(1))}
          htmlText={htmlQueue[0].text}
          onComplete={(convertedDataUrl) => {
            setImages(prev => [...prev, convertedDataUrl]);
            setHtmlQueue(prev => prev.slice(1));
          }}
        />
      )}

      {previewImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-background/90 backdrop-blur-sm" onClick={() => setPreviewImage(null)} />
          <div className="relative z-10 w-full max-w-5xl h-full max-h-[90vh] flex flex-col bg-card rounded-2xl shadow-2xl border cursor-auto overflow-hidden">
            <div className="shrink-0 flex items-center justify-between p-4 border-b bg-muted/30">
              <h3 className="font-bold text-sm text-muted-foreground uppercase tracking-wider">미리보기 (Preview)</h3>
              <button type="button" onClick={() => setPreviewImage(null)} className="p-2 hover:bg-muted rounded-lg transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-muted/10">
              <MediaRenderer src={previewImage} alt="미리보기 화면" className="max-w-4xl mx-auto w-full" />
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between mb-6">
        <h2 className="text-lg font-semibold">
          {editMode ? '작품 수정' : `새 ${type === 'long' ? '로그 백업/작품' : '단편만화'} 업로드`}
        </h2>
        <button onClick={onClose} className="p-1 hover:bg-muted rounded-lg">
          <X className="w-5 h-5" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Title */}
        <div className="space-y-2">
          <Label htmlFor="title">제목</Label>
          <Input
            id="title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="제목을 입력하세요"
            className="bg-input"
            required
          />
        </div>

        {/* Description */}
        <div className="space-y-2">
          <Label htmlFor="description">설명</Label>
          <Textarea
            id="description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="작품에 대한 설명을 작성하세요"
            rows={3}
            className="resize-none bg-input"
          />
        </div>

        {/* Image Upload */}
        <div className="space-y-2">
          <Label>페이지 콘텐츠 (webp, jpg, png, apng, gif, mp4, html 등 허용)</Label>
          <input
            ref={fileInputRef}
            type="file"
            accept=".webp,.jpg,.jpeg,.png,.apng,.gif,.mp4,.html,.htm,image/*,video/mp4,text/html"
            multiple
            onChange={handleImageUpload}
            className="hidden"
          />
          
          <div className="space-y-2">
            {images.map((img, index) => (
              <div 
                key={index} 
                draggable
                onDragStart={() => handleDragStart(index)}
                onDragEnter={() => handleDragEnter(index)}
                onDragEnd={handleDragEnd}
                onDragOver={handleDragOver}
                className="flex items-center gap-2 p-2 rounded-lg bg-muted/50 cursor-move hover:bg-muted transition-colors"
              >
                <GripVertical className="w-4 h-4 text-muted-foreground" />
                <div className="w-12 h-16 object-cover rounded overflow-hidden drag-none pointer-events-none">
                  <MediaRenderer src={img} alt={`페이지 ${index + 1}`} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 pointer-events-none">
                  <span className="text-sm font-medium">페이지 {index + 1}</span>
                  {index === 0 && (
                    <span className="ml-2 text-xs px-1.5 py-0.5 rounded bg-primary text-primary-foreground">
                      썸네일
                    </span>
                  )}
                </div>
                <div className="flex gap-1">
                  {index > 0 && (
                    <button
                      type="button"
                      onClick={(e) => { e.stopPropagation(); moveImage(index, index - 1); }}
                      className="p-1 text-xs hover:bg-muted-foreground/20 rounded cursor-pointer"
                    >
                      위로
                    </button>
                  )}
                  {index < images.length - 1 && (
                    <button
                      type="button"
                      onClick={(e) => { e.stopPropagation(); moveImage(index, index + 1); }}
                      className="p-1 text-xs hover:bg-muted-foreground/20 rounded cursor-pointer"
                    >
                      아래로
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); setPreviewImage(img); }}
                    className="p-1 text-primary hover:bg-primary/10 rounded cursor-pointer"
                    title="미리보기"
                  >
                    <Eye className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); removeImage(index); }}
                    className="p-1 text-destructive hover:bg-destructive/10 rounded cursor-pointer"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
            
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="w-full p-4 rounded-lg border-2 border-dashed border-border hover:border-primary flex items-center justify-center gap-2 transition-colors"
            >
              <Upload className="w-5 h-5 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">이미지 추가</span>
            </button>
          </div>
          <p className="text-xs text-muted-foreground">
            첫 번째 이미지가 썸네일로 사용됩니다. 업로드된 이미지는 자동으로 최적화됩니다. (드래그하여 순서 변경 가능)
          </p>
        </div>

        {/* Submit */}
        <div className="flex justify-end gap-2 pt-2">
          <Button type="button" variant="outline" onClick={onClose}>
            취소
          </Button>
          <Button type="submit" disabled={isSaving || !title.trim() || images.length === 0}>
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? '저장 중...' : (editMode ? '수정 완료' : '업로드')}
          </Button>
        </div>
      </form>
    </div>
  );
}
