import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Check, ImageIcon } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';

interface HtmlLogPreviewProps {
  isOpen: boolean;
  onClose: () => void;
  htmlText: string;
  onComplete: (convertedHtmlDataUrl: string) => void;
}

interface ParsedLogEntry {
  tab: string;
  name: string;
  color: string;
  text: string;
  isSystem: boolean;
}

function isSystemLog(text: string) {
  return /(CC<=\s*\d+|choice|\b\d+d\d+\b)/i.test(text);
}

function buildOutputDataUrl(htmlText: string, thumbnails: Record<string, string>, bgImage: string) {
  const cleanHtml = htmlText.replace(/<!--\s*LOG_META:[\s\S]*?-->/g, '');
  const meta = btoa(unescape(encodeURIComponent(JSON.stringify({ thumbnails, bgImage }))));
  const separator = cleanHtml.includes('</body>') ? '\n' : '\n\n';
  const output = `${cleanHtml}${separator}<!-- LOG_META:${meta} -->`;

  return `data:text/html;charset=utf-8,${encodeURIComponent(output)}`;
}

function parseHtmlLogEntries(htmlText: string) {
  const doc = new DOMParser().parseFromString(htmlText, 'text/html');
  const entries: ParsedLogEntry[] = [];
  const speakers = new Set<string>();

  doc.querySelectorAll('p').forEach((p) => {
    const color = p.style.color || '#333333';
    const spans = p.querySelectorAll('span');
    let tab = 'MAIN';
    let name = 'System';
    let text = '';

    if (spans.length >= 3) {
      tab = spans[0].textContent?.trim().replace(/\[|\]/g, '') || 'MAIN';
      name = spans[1].textContent?.replace(/ :$/, '').trim() || 'Unknown';
      text = Array.from(spans).slice(2).map((s) => s.innerHTML).join('');
    } else {
      const raw = p.textContent || '';
      const match = raw.match(/\[(.*?)\]\s*(.*?)\s*:\s*(.*)/);
      if (match) {
        tab = match[1] || 'MAIN';
        name = match[2]?.trim() || 'Unknown';
        text = match[3] || '';
      } else {
        text = p.innerHTML || raw;
      }
    }

    if (name) speakers.add(name);
    entries.push({
      tab,
      name,
      color,
      text,
      isSystem: isSystemLog(text),
    });
  });

  return { entries, speakers: Array.from(speakers) };
}

function escapeHtml(input: string) {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function buildPreviewHtml(entries: ParsedLogEntry[], thumbnails: Record<string, string>, bgImage: string) {
  const tabGroups: Array<{ tab: string; entries: ParsedLogEntry[]; isSystem: boolean; isInfo: boolean }> = [];

  for (const entry of entries) {
    const tab = (entry.tab || 'MAIN').trim();
    const isInfo = tab.toLowerCase().includes('info') || tab === '정보';

    if (entry.isSystem) {
      tabGroups.push({ tab, entries: [entry], isSystem: true, isInfo: false });
      continue;
    }

    const lastGroup = tabGroups[tabGroups.length - 1];
    if (lastGroup && !lastGroup.isSystem && lastGroup.tab === tab) {
      lastGroup.entries.push(entry);
    } else {
      tabGroups.push({ tab, entries: [entry], isSystem: false, isInfo });
    }
  }

  const speakerThumbEntries = Object.entries(thumbnails).filter(([, value]) => !!value);
  const speakerThumbStyles = speakerThumbEntries
    .map(([speaker, value], index) => `.speaker-thumb-${index} { background-image: url('${value}'); }`)
    .join('\n');
  const speakerThumbClass = new Map(speakerThumbEntries.map(([speaker], index) => [speaker, `speaker-thumb-${index}`]));

  const renderEntry = (entry: ParsedLogEntry) => {
    const thumbClass = speakerThumbClass.get(entry.name);
    const thumbMarkup = thumbClass ? `<div class="log-avatar ${thumbClass}"></div>` : `<div class="log-avatar log-avatar--empty"></div>`;

    return `
      <article class="message-card">
        <div class="message-head">
          ${thumbMarkup}
          <div class="message-meta">
            <div class="message-tab">${escapeHtml(entry.tab || 'MAIN')}</div>
            <div class="message-name" style="color:${escapeHtml(entry.color)}">${escapeHtml(entry.name || 'Unknown')}</div>
          </div>
        </div>
        <div class="message-body ccfolia-text" style="color:${escapeHtml(entry.color)}">${entry.text}</div>
      </article>
    `;
  };

  const groupsHtml = tabGroups.map((group) => {
    if (group.isSystem) {
      return `
        <section class="system-wrap">
          <div class="system-card ccfolia-text">${group.entries[0].text}</div>
        </section>
      `;
    }

    if (group.isInfo) {
      return `
        <section class="info-panel">
          <header class="info-head">
            <span class="info-badge">${escapeHtml(group.tab)}</span>
          </header>
          <div class="message-stack">
            ${group.entries.map(renderEntry).join('')}
          </div>
        </section>
      `;
    }

    if (group.tab.toUpperCase() === 'MAIN') {
      return `
        <section class="tab-group">
          <div class="tab-summary no-arrow" style="cursor: default;">${escapeHtml(group.tab)}</div>
          <div class="message-stack">
            ${group.entries.map(renderEntry).join('')}
          </div>
        </section>
      `;
    }

    return `
      <details class="tab-group" open>
        <summary class="tab-summary">${escapeHtml(group.tab)}</summary>
        <div class="message-stack">
          ${group.entries.map(renderEntry).join('')}
        </div>
      </details>
    `;
  }).join('\n');

  return `
<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>HTML 로그 미리보기</title>
<style>
  ${speakerThumbStyles}
  :root {
    color-scheme: light;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    font-family: "Malgun Gothic", "Apple SD Gothic Neo", system-ui, sans-serif;
    background: ${bgImage ? `url('${bgImage}') center/cover fixed` : '#f7f4ee'};
    color: #151515;
  }
  .page-shell {
    min-height: 100vh;
    padding: 28px 18px 40px;
    background: ${bgImage ? 'rgba(247, 244, 238, 0.68)' : 'transparent'};
    backdrop-filter: blur(10px);
  }
  .log-container {
    width: min(920px, 100%);
    margin: 0 auto;
    display: grid;
    gap: 16px;
  }
  .tab-group {
    border: 1px solid rgba(15, 23, 42, 0.12);
    border-radius: 20px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.08);
  }
  .tab-summary {
    list-style: none;
    cursor: pointer;
    padding: 16px 20px;
    font-weight: 800;
    letter-spacing: 0.04em;
    display: flex;
    align-items: center;
    gap: 10px;
    background: linear-gradient(90deg, rgba(255,255,255,0.95), rgba(246,242,235,0.95));
  }
  .tab-summary::before {
    content: '▸';
    transition: transform .2s ease;
  }
  .tab-group[open] .tab-summary::before {
    transform: rotate(90deg);
  }
  .tab-summary.no-arrow::before {
    display: none;
  }
  .message-stack {
    padding: 18px 18px 20px;
    display: grid;
    gap: 14px;
  }
  .message-card {
    border: 1px solid rgba(15, 23, 42, 0.1);
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
    overflow: hidden;
  }
  .message-head {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 16px 16px 10px;
  }
  .log-avatar {
    width: 46px;
    height: 46px;
    border-radius: 14px;
    background-size: cover;
    background-position: center;
    flex-shrink: 0;
    border: 1px solid rgba(15, 23, 42, 0.08);
  }
  .log-avatar--empty {
    background: linear-gradient(135deg, #e2e8f0, #cbd5e1);
  }
  .message-meta { min-width: 0; }
  .message-tab {
    font-size: 11px;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: rgba(15, 23, 42, 0.55);
    margin-bottom: 4px;
  }
  .message-name {
    font-size: 16px;
    font-weight: 900;
    line-height: 1.2;
    word-break: break-word;
  }
  .message-body {
    padding: 0 16px 16px 74px;
    font-size: 15px;
    line-height: 1.75;
    word-break: break-word;
    overflow-wrap: anywhere;
  }
  .info-panel {
    border: 1px solid rgba(59, 130, 246, 0.2);
    border-radius: 20px;
    background: rgba(239, 246, 255, 0.88);
    box-shadow: 0 16px 40px rgba(59, 130, 246, 0.08);
    overflow: hidden;
  }
  .info-head {
    padding: 16px 20px 0;
  }
  .info-badge {
    display: inline-flex;
    align-items: center;
    padding: 7px 12px;
    border-radius: 999px;
    background: #0f172a;
    color: white;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: .08em;
  }
  .system-wrap {
    display: flex;
    justify-content: center;
  }
  .system-card {
    width: min(100%, 720px);
    border: 1px solid rgba(59, 130, 246, 0.26);
    border-radius: 18px;
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.95), rgba(30, 41, 59, 0.95));
    color: #f8fafc;
    padding: 16px 18px;
    box-shadow: 0 18px 36px rgba(15, 23, 42, 0.16);
    text-align: left;
    overflow-wrap: anywhere;
  }
  .ccfolia-text img {
    max-width: 100%;
    height: auto;
    border-radius: 10px;
    display: block;
    margin: 10px 0;
  }
  @media (max-width: 720px) {
    .page-shell { padding: 18px 12px 30px; }
    .message-body { padding-left: 16px; }
    .message-head { padding: 14px 14px 10px; }
  }
</style>
</head>
<body>
  <div class="page-shell">
    <div class="log-container">
      ${groupsHtml}
    </div>
  </div>
</body>
</html>
`;
}

export function HtmlLogPreview({ isOpen, onClose, htmlText, onComplete }: HtmlLogPreviewProps) {
  const [thumbnails, setThumbnails] = useState<Record<string, string>>({});
  const [bgImage, setBgImage] = useState<string>('');
  const bgInputRef = useRef<HTMLInputElement>(null);
  const faceInputRefs = useRef<Record<string, HTMLInputElement | null>>({});

  const { entries, speakers } = useMemo(() => parseHtmlLogEntries(htmlText), [htmlText]);
  const previewDataUrl = useMemo(
    () => (htmlText ? buildOutputDataUrl(htmlText, thumbnails, bgImage) : ''),
    [htmlText, thumbnails, bgImage]
  );
  const previewHtml = useMemo(
    () => (htmlText ? buildPreviewHtml(entries, thumbnails, bgImage) : ''),
    [entries, htmlText, thumbnails, bgImage]
  );

  useEffect(() => {
    if (!isOpen) {
      setThumbnails({});
      setBgImage('');
    }
  }, [isOpen]);

  const handleThumbnailUpload = (speaker: string, file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setThumbnails((prev) => ({
        ...prev,
        [speaker]: event.target?.result as string,
      }));
    };
    reader.readAsDataURL(file);
  };

  const handleBgUpload = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setBgImage(event.target?.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleComplete = () => {
    onComplete(previewDataUrl);
  };

  const handleOpenPreview = () => {
    if (!previewHtml) return;

    const popup = window.open('', '_blank', 'noopener,noreferrer,width=1280,height=960');
    if (!popup) return;

    popup.document.open();
    popup.document.write(previewHtml);
    popup.document.close();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>HTML 로그 변환 설정</DialogTitle>
        </DialogHeader>

        <div className="grid gap-6 lg:grid-cols-[360px_minmax(0,1fr)]">
          <div className="space-y-6">
            <div className="space-y-3">
              <h3 className="font-semibold text-lg border-b pb-2">배경 이미지 설정</h3>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                ref={bgInputRef}
                onChange={(e) => {
                  if (e.target.files?.[0]) handleBgUpload(e.target.files[0]);
                  e.target.value = '';
                }}
              />
              <div className="flex items-center gap-3 flex-wrap">
                <Button variant="outline" onClick={() => bgInputRef.current?.click()}>
                  <ImageIcon className="w-4 h-4 mr-2" />
                  배경 이미지 선택
                </Button>
                {bgImage && (
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Check className="w-4 h-4 text-green-500" />
                    설정됨
                    <Button variant="ghost" size="sm" onClick={() => setBgImage('')}>
                      취소
                    </Button>
                  </div>
                )}
              </div>
              <p className="text-sm text-muted-foreground">설정하지 않으면 기본 흰색 배경이 사용됩니다.</p>
            </div>

            <div className="space-y-3">
              <h3 className="font-semibold text-lg border-b pb-2">발언자 썸네일 설정</h3>
              <div className="space-y-3 max-h-[42vh] overflow-y-auto pr-1">
                {speakers.length > 0 ? speakers.map((speaker) => (
                  <div key={speaker} className="flex items-center gap-3 p-3 border rounded-lg bg-muted/20">
                    <div
                      className="w-12 h-12 rounded-lg bg-muted flex items-center justify-center bg-cover bg-center shrink-0 border"
                      style={{ backgroundImage: thumbnails[speaker] ? `url('${thumbnails[speaker]}')` : 'none' }}
                    >
                      {!thumbnails[speaker] && <span className="text-[10px] text-muted-foreground">No img</span>}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-sm truncate" title={speaker}>{speaker}</p>
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        ref={(el) => {
                          faceInputRefs.current[speaker] = el;
                        }}
                        onChange={(e) => {
                          if (e.target.files?.[0]) handleThumbnailUpload(speaker, e.target.files[0]);
                          e.target.value = '';
                        }}
                      />
                      <Button
                        variant="secondary"
                        size="sm"
                        className="text-xs h-7 mt-1 w-full"
                        onClick={() => faceInputRefs.current[speaker]?.click()}
                      >
                        이미지 업로드
                      </Button>
                    </div>
                  </div>
                )) : (
                  <div className="rounded-lg border border-dashed p-4 text-sm text-muted-foreground">
                    발언자 정보를 읽는 중입니다. HTML 구조에 따라 일부 이름은 수동 표시될 수 있습니다.
                  </div>
                )}
              </div>
            </div>

            <div className="flex justify-between gap-2 pt-2 border-t flex-wrap">
              <Button variant="secondary" onClick={handleOpenPreview} disabled={!previewHtml}>
                새 창 미리보기
              </Button>
              <Button variant="outline" onClick={onClose}>
                취소
              </Button>
              <Button onClick={handleComplete} className="bg-primary text-primary-foreground">
                변환 및 적용완료
              </Button>
            </div>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between gap-3">
              <h3 className="font-semibold text-lg">미리보기 안내</h3>
              <span className="text-xs text-muted-foreground">화면이 넓은 새 창에서 확인합니다.</span>
            </div>
            <div className="rounded-xl border bg-muted/20 p-6 shadow-sm min-h-[68vh] flex flex-col items-center justify-center text-center gap-4">
              <div className="w-16 h-16 rounded-2xl bg-background border flex items-center justify-center shadow-sm">
                <ImageIcon className="w-8 h-8 text-primary" />
              </div>
              <div className="space-y-2 max-w-md">
                <p className="font-semibold text-lg">미리보기는 새 창에서 열립니다</p>
                <p className="text-sm text-muted-foreground">
                  썸네일, 배경, 연속 탭 그룹, 시스템 판정 레이아웃을 포함한 전체 결과를 넓은 화면으로 확인할 수 있습니다.
                </p>
              </div>
              <Button onClick={handleOpenPreview} disabled={!previewHtml}>
                새 창 미리보기 열기
              </Button>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}